function mountLegacy(app) {
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>(Number(v)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}), dt=v=>new Date(v).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}), day=v=>new Date(v).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo',day:'numeric',month:'long'}), clock=v=>new Date(v).toLocaleTimeString('pt-BR',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit'}), local=v=>v?new Date(new Date(v).getTime()-3*3600000).toISOString().slice(0,16):'', utc=v=>v?new Date(v+':00-03:00').toISOString():null;
const status={draft:'Rascunho',published:'Publicado',cancelled:'Cancelado',pending:'Aguardando pagamento',paid:'Pago',expired:'Expirado',review:'Revisão necessária',refunding:'Reembolso em andamento',refunded:'Reembolsado',charged_back:'Contestação',valid:'Válido',invalid:'Inválido',used:'Já utilizado'};
const pill=s=>`<span class="pill ${esc(s)}">${esc(status[s]||s)}</span>`;
let config={}, user=null, route=location.pathname, timer, stream, scanTimer;
let guestKey='';if(route.startsWith('/pedido/')){const orderId=route.split('/')[2];const k=new URLSearchParams(location.hash.slice(1)).get('chave');try{if(k)sessionStorage.setItem('ln-order:'+orderId,k);guestKey=k||sessionStorage.getItem('ln-order:'+orderId)||'';}catch{guestKey=k||'';}if(k)history.replaceState(null,'',location.pathname+location.search);}

async function api(path,method='GET',data){let r=await fetch('/api'+path,{method,credentials:'same-origin',headers:{...(method==='GET'?{}:{'Content-Type':'application/json'}),...(guestKey?{'X-Guest-Key':guestKey}:{})},...(method==='GET'?{}:{body:JSON.stringify(data||{})})});let j=await r.json();if(!r.ok)throw Error(j.error||'Não foi possível concluir.');return j;}
function toast(t){const e=$('#toast');e.textContent=t;e.className='toast';clearTimeout(timer);timer=setTimeout(()=>{e.className='';e.textContent='';},4200);}
function err(e){toast(e.message||String(e));}
function bind(selector,event,fn){let el=$(selector);if(el)el.addEventListener(event,fn);}
async function guarded(el,fn){if(el?.disabled)return; if(el)el.disabled=true;try{await fn();}catch(e){err(e);}finally{if(el)el.disabled=false;}}
function field(label,name,value='',type='text',attrs=''){return `<div class="field"><label for="${esc(name)}">${esc(label)}</label><input id="${esc(name)}" name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${attrs}></div>`;}
const logo=`<img class="logo" src="/assets/logo.svg" alt="Long Night">`;
const link=(href,label,cls='')=>`<a class="action ${cls}" href="${esc(href)}">${esc(label)}</a>`;
function header(){return `${config.mode==='demo'?'<div class="demo-banner">AMBIENTE DEMONSTRATIVO • Eventos e imagens ilustrativos • Nenhuma cobrança real</div>':''}<header class="header"><div class="wrap"><a href="/" aria-label="Long Night, início">${logo}</a><nav id="public-nav" class="site-nav" aria-label="Navegação principal">${[['/#inicio','Início'],['/#eventos','Eventos'],['/#galeria','Fotos'],['/#sobre','Sobre']].map(([href,t])=>`<a href="${href}" class="${route===href?'is-current':''}" ${route===href?'aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="hstack"><a class="action action-outline" href="${user?.role==='admin'?'/admin':user?.role==='staff'?'/portaria':'/meus-ingressos'}">${user?.role==='admin'?'Painel':user?.role==='staff'?'Portaria':'Meus ingressos'}</a><button class="mobile-nav" id="menu" aria-expanded="false" aria-controls="public-nav" aria-label="Abrir menu">☰</button></div></div></header>`;}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-grid"><a href="/" aria-label="Long Night">${logo}</a><div><h2>Navegação</h2><a href="/">Início</a><a href="/#eventos">Eventos</a><a href="/#galeria">Fotos</a><a href="/#sobre">Sobre</a></div><div><h2>Suporte</h2><a href="/#faq">Dúvidas frequentes</a><a href="/termos">Termos de uso</a><a href="/privacidade">Privacidade</a>${user?'<button id="logout" class="action action-muted is-small">Sair da conta</button>':'<a href="/admin">Área da equipe</a>'}</div><div><h2>Acompanhe a Long Night</h2><a href="https://www.instagram.com/long._night/" target="_blank" rel="noopener noreferrer">@long._night</a><a class="action action-outline" href="https://www.instagram.com/long._night/" target="_blank" rel="noopener noreferrer">Seguir no Instagram ↗</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Long Night. Todos os direitos reservados.</span><span>Eventos • Música • Experiências</span></div></div></footer>`;}
function shell(content){app.innerHTML=header()+`<main id="main" tabindex="-1">${content}</main>`+footer();bind('#menu','click',e=>{const n=$('.site-nav');n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(n.classList.contains('open')));});bind('#logout','click',e=>guarded(e.currentTarget,async()=>{await api('/logout','POST');location.href='/';}));}
function page(content){shell(`<div class="wrap page">${content}</div>`);}
function empty(t){return `<div class="empty">${esc(t)}</div>`;}
function eventMeta(e){return `<div class="event-meta"><span><i aria-hidden="true">▦</i>${esc(day(e.starts))} · ${esc(clock(e.starts))}</span><span><i aria-hidden="true">⌖</i>${esc(e.city)}</span><span><i aria-hidden="true">◷</i>${esc(e.venue)}</span></div>`;}
function safeReturn(){let p=new URLSearchParams(location.search).get('voltar')||'';return /^\/(?!\/)[\w/?=&%-]*$/.test(p)?p:'/meus-ingressos';}
function authPage(){let register=new URLSearchParams(location.search).get('cadastro')==='1';function draw(){page(`<div class="auth surface-panel stack"><div class="eyebrow">Sua conta Long Night</div><h1 class="page-title">${register?'Criar conta':'Entrar na sua conta'}</h1><p class="muted">${register?'Cadastre-se para comprar e acessar seus ingressos.':'Acesso reservado à equipe e às contas anteriores. Para comprar, não é necessário cadastro.'}</p><form id="auth-form" class="stack">${register?field('Nome completo','name','','text','required maxlength="100" autocomplete="name"'):''}${field('E-mail','email','','email','required autocomplete="email"')}${field('Senha','password','','password',`required minlength="${register?8:1}" maxlength="128" autocomplete="${register?'new-password':'current-password'}"`)}<button class="action is-full" type="submit">${register?'Criar conta':'Entrar'}</button><p id="auth-error" class="error" role="alert"></p></form>${config.mode==='demo'?'<div class="notice">Equipe de demonstração: admin@longnight.local / LongNight2026!<br>Portaria: portaria@longnight.local / Portaria2026!</div>':''}</div>`);bind('#toggle-auth','click',()=>{register=!register;draw();});bind('#auth-form','submit',async e=>{e.preventDefault();let form=e.currentTarget,btn=$('button[type=submit]',form);btn.disabled=true;try{user=await api(register?'/register':'/login','POST',Object.fromEntries(new FormData(form)));let target=safeReturn();location.href=user.role==='admin'?'/admin':user.role==='staff'?'/portaria':target;}catch(e){$('#auth-error').textContent=e.message;btn.disabled=false;}});}draw();}
function authRequired(roles){if(!user){location.href='/entrar?voltar='+encodeURIComponent(location.pathname+location.search);return false;}if(!roles.includes(user.role)){page(`<h1 class="page-title">Acesso restrito</h1><p class="lead">Sua conta não possui esta permissão.</p>${link('/','Voltar ao início')}`);return false;}return true;}
async function checkout(id){let e=await api('/events/'+id);let selected=new URLSearchParams(location.search).get('lote');let l=e.lots.find(l=>l.id===selected&&l.available)||e.lots.find(l=>l.available);if(!l||Date.parse(e.starts)<=Date.now()){page(`${empty('Não há ingressos disponíveis.')}${link('/evento/'+id,'Voltar ao evento')}`);return;}if(!authRequired(['customer']))return;let qty=1,coupon='',quote=null;page(`<a class="back" href="/evento/${esc(e.id)}">← Voltar ao evento</a><h1 class="page-title">Finalize sua compra</h1><p class="lead">1. Ingressos e dados · 2. Pagamento · 3. Confirmação</p><div class="split"><div class="surface-panel stack"><div class="hstack"><img class="image-preview" src="${esc(e.flyer)}" alt="Flyer do evento"><div><h2>${esc(e.title)}</h2>${eventMeta(e)}</div></div><hr class="divider"><form id="checkout-form" class="stack"><div class="field"><label for="lot">Lote</label><select id="lot" name="lot">${e.lots.filter(x=>x.available).map(x=>`<option value="${esc(x.id)}" ${x.id===l.id?'selected':''}>${esc(x.name)} — ${money(x.price)}</option>`).join('')}</select></div><div class="field"><label for="qty">Quantidade (até 10)</label><input id="qty" name="qty" type="number" min="1" max="${Math.min(10,l.remaining)}" value="1" required></div><div class="surface-panel stack"><strong>Comprador</strong><p>${esc(user.name)}<br><span class="muted">${esc(user.email)}</span></p></div><div class="field"><label for="coupon">Cupom de desconto (opcional)</label><div class="hstack"><input id="coupon" maxlength="30" placeholder="Código do cupom"><button id="apply" class="action action-muted" type="button">Aplicar</button></div></div><div class="check"><input id="agree" type="checkbox" required><label for="agree">Li os <a class="inline-link" href="/termos" target="_blank" rel="noopener noreferrer">termos de uso</a> e a <a class="inline-link" href="/privacidade" target="_blank" rel="noopener noreferrer">política de privacidade</a>.</label></div><p id="checkout-error" class="error" role="alert"></p></form></div><div class="surface-panel stack"><h2>Resumo do pedido</h2><div class="summary"><div><span>Ingresso</span><strong id="sum-unit">${money(l.price)}</strong></div><div><span>Quantidade</span><strong id="sum-qty">1</strong></div><div><span>Taxa adicional Long Night</span><strong>R$ 0,00</strong></div><div class="total"><span>Total</span><strong id="sum-total">${money(l.price)}</strong></div></div><hr class="divider"><h3>Pagamento</h3><p class="muted">${config.mode==='demo'?'Modo de demonstração: simule uma aprovação sem pagar.':'Pague por Pix ou cartão no ambiente seguro do Mercado Pago. Os meios e parcelas disponíveis são definidos pelo provedor.'}</p><button class="action is-full" type="submit" form="checkout-form" id="purchase">${config.mode==='demo'?'Criar pedido de teste':'Ir para pagamento →'}</button><small>Os ingressos serão liberados após confirmação do pagamento.</small></div></div>`);
async function update(){let current=e.lots.find(x=>x.id===$('#lot').value);$('#qty').max=Math.min(10,current.remaining);let q=Number($('#qty').value);if(!Number.isInteger(q)||q<1||q>Number($('#qty').max))throw Error('Quantidade inválida.');let c=$('#coupon').value.trim();quote=await api('/quote','POST',{event:id,lot:current.id,qty:q,coupon:c});qty=q;coupon=c;$('#sum-unit').textContent=money(quote.unit);$('#sum-qty').textContent=String(q);$('#sum-total').textContent=money(quote.total);$('#checkout-error').textContent='';}
bind('#apply','click',e=>guarded(e.currentTarget,update));bind('#qty','change',()=>update().catch(err));bind('#lot','change',()=>update().catch(err));bind('#checkout-form','submit',async ev=>{ev.preventDefault();guarded($('#purchase'),async()=>{await update();let o=await api('/orders','POST',{event:id,lot:$('#lot').value,qty,coupon});location.href=o.url;});});}
async function ordersPage(){if(!user){let saved=[];try{for(let i=0;i<sessionStorage.length;i++){let k=sessionStorage.key(i);if(k.startsWith('ln-order:'))saved.push({id:k.slice(9),key:sessionStorage.getItem(k)});}}catch{}page(`<h1 class="page-title">Meus ingressos</h1><p class="lead">Abra o link privado enviado ao e-mail da compra. Os pedidos desta sessão aparecem abaixo.</p><div class="stack">${saved.map(x=>link('/pedido/'+x.id+'#chave='+x.key,'Abrir pedido '+x.id.slice(0,8),'action-outline')).join('')||empty('Nenhum pedido salvo nesta sessão.')}</div>`);return;}if(!authRequired(['customer']))return;let orders=await api('/orders');page(`<div class="hstack between"><div><div class="eyebrow">Minha conta</div><h1 class="page-title">Meus ingressos</h1><p class="lead">${esc(user.name)} · ${esc(user.email)}</p></div><button class="action action-muted" id="signout">Sair</button></div><div class="hstack" id="filters"><button class="action is-small" data-filter="all">Todos</button><button class="action action-muted is-small" data-filter="paid">Pagos</button><button class="action action-muted is-small" data-filter="pending">Pendentes</button><button class="action action-muted is-small" data-filter="other">Outros</button></div><div class="stack" id="order-list"></div>`);function draw(filter='all'){let list=orders.filter(o=>filter==='all'||(filter==='other'?!['paid','pending'].includes(o.status):o.status===filter));$('#order-list').innerHTML=list.length?list.map(o=>`<article class="surface-panel order-card"><img src="${esc(o.flyer)}" alt=""><div class="stack"><h2 class="item-title">${esc(o.title)}</h2><p>${esc(dt(o.starts))} · ${esc(o.city)}<br>${o.qty} ingresso(s) · ${esc(o.lot_name)} · ${money(o.total)}</p><div>${pill(o.status)}</div></div>${link('/pedido/'+o.id,'Ver pedido →','action-outline')}</article>`).join(''):empty('Nenhum pedido nesta categoria.');}draw();$$('[data-filter]').forEach(b=>b.onclick=()=>{$$('[data-filter]').forEach(x=>x.className='action action-muted is-small');b.className='action is-small';draw(b.dataset.filter);});bind('#signout','click',e=>guarded(e.currentTarget,async()=>{await api('/logout','POST');location.href='/';}));}
async function orderPage(id){if(!guestKey&&!user){page(`<h1 class="page-title">Acesse seu ingresso</h1><p class="lead">Abra o link privado enviado ao seu e-mail ou entre na sua conta antiga.</p>${link('/entrar','Entrar')}${link('/','Voltar ao site','action-outline')}`);return;}let params=new URLSearchParams(location.search);let pid=params.get('payment_id')||params.get('collection_id');if(pid&&/^\d+$/.test(pid)&&config.mode!=='demo'){try{await api('/orders/'+id+'/sync','POST',{paymentId:pid});}catch(e){toast(e.message);}history.replaceState(null,'','/pedido/'+id);}let o=await api('/orders/'+id);let paid=o.status==='paid';page(`<a class="back no-print" href="${user?.role==='admin'?'/admin/vendas':'/#eventos'}">← ${user?.role==='admin'?'Vendas':'Eventos'}</a><div class="eyebrow">Pedido ${esc(o.id.slice(0,8).toUpperCase())}</div><h1 class="page-title">${paid?'Seus ingressos estão disponíveis':esc(status[o.status]||o.status)}</h1><div class="surface-panel stack"><div class="hstack between"><h2>${esc(o.title)}</h2>${pill(o.status)}</div><p>${esc(dt(o.starts))} · ${esc(o.venue)} · ${esc(o.city)}<br>${o.qty} ingresso(s) · ${esc(o.lot_name)} · ${money(o.total)}</p>${o.status==='pending'?`<p class="notice">Reserva até ${esc(dt(o.expires))}. O ingresso só será emitido após a aprovação.</p><div class="hstack no-print">${config.mode==='demo'?'<button id="simulate" class="action">Simular pagamento aprovado</button><button id="cancel" class="action action-danger">Cancelar reserva</button>':o.checkout_url?link(o.checkout_url,'Continuar no Mercado Pago'):''}<button id="refresh" class="action action-muted">Atualizar status</button></div>`:config.mode!=='demo'&&['expired','review','refunding'].includes(o.status)?'<button id="refresh" class="action action-muted no-print">Consultar Mercado Pago</button>':''}${['expired','review','refunding','charged_back','refunded'].includes(o.status)?'<p class="muted">Se você já realizou um pagamento, entre em contato com a organização para verificar o status antes de comprar novamente.</p>':''}</div>${guestKey?`<div class="surface-panel stack no-print"><h2>Guarde seu acesso</h2><p>Salve o link privado para abrir o ingresso em outro aparelho. Não compartilhe com terceiros.</p><input id="private-link" aria-label="Link privado do ingresso" readonly value="${esc(location.origin+'/pedido/'+id+'#chave='+guestKey)}"><button id="copy-private" class="action action-outline">Copiar link privado</button></div>`:''}${paid?`<section class="section compact"><div class="section-head"><h2>Ingressos digitais</h2><button id="print" class="action action-muted no-print">Imprimir / salvar PDF</button></div><div class="ticket-grid">${o.tickets.map((t,i)=>`<article class="ticket"><div class="eyebrow">Long Night · Ingresso ${i+1}/${o.qty}</div><h2 class="item-title">${esc(o.title)}</h2><p>${esc(dt(o.starts))}<br>${esc(o.lot_name)}</p><div>${t.void?pill('cancelled'):t.used_at?pill('used'):pill('valid')}</div><img class="qr" data-ticket="${esc(t.id)}" alt="QR Code do ingresso ${i+1}"><code>${esc(t.token)}</code><p class="muted">Apresente na entrada. Não compartilhe este código.</p></article>`).join('')}</div></section>`:''}`);bind('#copy-private','click',async()=>{try{await navigator.clipboard.writeText($('#private-link').value);toast('Link copiado.');}catch{$('#private-link').select();toast('Selecione e copie o link.');}});if(paid){for(const img of $$('[data-ticket]')){try{let q=await api('/tickets/'+img.dataset.ticket+'/qr');img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(q.svg);}catch(e){img.alt=e.message;}}bind('#print','click',()=>window.print());}bind('#simulate','click',e=>guarded(e.currentTarget,async()=>{await api('/orders/'+id+'/demo-pay','POST');location.reload();}));bind('#cancel','click',e=>guarded(e.currentTarget,async()=>{await api('/orders/'+id+'/cancel','POST');location.reload();}));bind('#refresh','click',e=>guarded(e.currentTarget,async()=>{if(config.mode!=='demo')await api('/orders/'+id+'/sync','POST');location.reload();}));}
const adminLinks=[['/admin','Dashboard'],['/admin/eventos','Eventos'],['/admin/vendas','Vendas e pedidos'],['/admin/participantes','Participantes'],['/admin/cupons','Cupons'],['/admin/configuracoes','Configurações'],['/portaria','Portaria / QR Code']];
function adminShell(title,content,actions=''){app.innerHTML=`${config.mode==='demo'?'<div class="demo-banner">AMBIENTE DEMONSTRATIVO • Não processa dinheiro real</div>':''}<div class="admin-shell"><aside class="sidebar" id="sidebar" aria-label="Administração"><nav aria-label="Menu administrativo"><a href="/admin">${logo}</a>${adminLinks.map(([p,t])=>`<a href="${p}" class="${route===p||(p!=='/admin'&&route.startsWith(p+'/'))?'is-current':''}" ${route===p?'aria-current="page"':''}>${t}</a>`).join('')}<hr class="divider"><a href="/">Ver site público ↗</a><button id="admin-logout">Sair da conta</button></nav></aside><main id="main" tabindex="-1" class="admin-main"><button class="action action-muted is-small mobile-admin" id="admin-menu" aria-expanded="false" aria-controls="sidebar">☰ Menu administrativo</button><div class="admin-top"><div><div class="eyebrow">Long Night / Administração</div><h1>${esc(title)}</h1></div><div class="hstack">${actions}</div></div>${content}</main></div>`;bind('#admin-menu','click',e=>{const open=$('#sidebar').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));});bind('#admin-logout','click',e=>guarded(e.currentTarget,async()=>{await api('/logout','POST');location.href='/entrar';}));}
function table(headers,rows){return rows.length?`<div class="data-scroll" tabindex="0" role="region" aria-label="Tabela de dados com rolagem"><table class="data-table"><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('Nenhum registro encontrado.');}
async function dashboard(){let d=await api('/admin/dashboard');let max=Math.max(1,...d.series.map(s=>s.total));adminShell('Painel de controle',`<p class="lead">Acompanhe os resultados e organize seus próximos eventos.</p><div class="kpis">${[['Eventos ativos',d.events],['Ingressos vendidos',d.tickets],['Receita bruta aprovada',money(d.revenue)],['Check-ins realizados',d.checkins]].map(([a,b])=>`<div class="kpi"><small>${a}</small><strong>${esc(b)}</strong></div>`).join('')}</div><div class="surface-panel stack"><h2>Vendas dos últimos 30 dias</h2>${d.series.length?`<div class="chart">${d.series.map(s=>`<div class="bar-col"><small>${money(s.total)}</small><svg role="img" viewBox="0 0 30 130" preserveAspectRatio="none" aria-label="${esc(s.day)}: ${money(s.total)}"><rect x="6" width="18" y="${130-120*s.total/max}" height="${120*s.total/max}" rx="2" fill="#cba568"/></svg><small>${esc(s.day.slice(5))}</small></div>`).join('')}</div>`:empty('As vendas aparecerão aqui após o primeiro pagamento.')}</div><section class="section compact"><div class="surface-panel"><div class="hstack between"><h2>Pedidos recentes</h2>${link('/admin/vendas','Ver todos','action-outline is-small')}</div>${table(['Pedido','Evento','Comprador','Qtd.','Valor','Status'],d.recent.map(o=>[`<a href="/pedido/${esc(o.id)}">${esc(o.id.slice(0,8))}</a>`,esc(o.title),esc(o.name),o.qty,money(o.total),pill(o.status)]))}</div></section>`,link('/admin/eventos/novo','+ Novo evento'));}
async function adminEvents(){let events=await api('/admin/events');adminShell('Gerenciar eventos',`<p class="lead">Cadastre, edite e publique os eventos. Alterações são refletidas automaticamente no site.</p><div class="surface-panel stack">${events.length?events.map(e=>{let cap=e.lots.reduce((s,x)=>s+x.capacity,0),reserved=e.lots.reduce((s,x)=>s+x.capacity-x.remaining,0);return `<article class="order-card"><img src="${esc(e.flyer)}" alt=""><div><h2 class="item-title">${esc(e.title)}</h2><p class="muted">${esc(dt(e.starts))} · ${esc(e.city)} · ${reserved}/${cap} ocupados (inclui reservas)</p><div class="hstack">${pill(e.status)}${e.status==='published'?`<a class="inline-link" href="/evento/${esc(e.id)}" target="_blank" rel="noopener noreferrer">Ver página ↗</a>`:''}</div></div>${link('/admin/eventos/'+e.id,'Editar evento','action-outline is-small')}</article><hr class="divider">`;}).join(''):empty('Cadastre seu primeiro evento.')}</div>`,link('/admin/eventos/novo','+ Novo evento'));}
async function adminEdit(id){let existing=id!=='novo',e=existing?await api('/admin/events/'+id):{title:'',description:'',venue:'',address:'',city:'Cascavel – PR',starts:'',ends:'',age:18,flyer:'/assets/hero.svg',status:'draft',lots:[]};let lots=e.lots.map(l=>({...l})),imageData=null;if(!lots.length)lots.push({name:'1º lote',price:4000,capacity:100,opens:null,closes:null,active:1});adminShell(existing?'Editar evento':'Criar novo evento',`<a class="back" href="/admin/eventos">← Todos os eventos</a><form id="event-form" class="stack"><div class="split"><div class="surface-panel stack"><h2>Informações principais</h2><div class="form-grid">${field('Nome do evento','title',e.title,'text','required maxlength="120"')}${field('Local / espaço','venue',e.venue,'text','required maxlength="120"')}${field('Endereço','address',e.address,'text','required maxlength="250"')}${field('Cidade / UF','city',e.city,'text','required maxlength="100"')}${field('Início (horário de Brasília)','starts',local(e.starts),'datetime-local','required')}${field('Término (horário de Brasília)','ends',local(e.ends),'datetime-local','required')}${field('Classificação etária (0 = livre)','age',e.age,'number','min="0" max="99" required')}</div><div class="field"><label for="description">Descrição, atrações e regras</label><textarea id="description" name="description" required maxlength="4000">${esc(e.description)}</textarea></div></div><div class="surface-panel stack"><h2>Capa / flyer</h2><img id="preview" class="image-preview" src="${esc(e.flyer)}" alt="Prévia do flyer"><div class="field"><label for="flyer">Enviar imagem</label><input id="flyer" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG ou WebP • até 3 MB</small></div><div class="field"><label for="event-status">Visibilidade</label><select id="event-status" name="status"><option value="draft" ${e.status==='draft'?'selected':''}>Rascunho</option><option value="published" ${e.status==='published'?'selected':''}>Publicado</option>${existing?`<option value="cancelled" ${e.status==='cancelled'?'selected':''}>Cancelado</option>`:''}</select></div><p class="notice">A publicação disponibiliza o evento no site. Cancelar um evento interrompe vendas e check-ins; reembolsos são tratados na área de vendas.</p></div></div><div class="surface-panel stack"><div class="hstack between"><h2>Lotes de ingresso</h2><button type="button" id="add-lot" class="action action-outline is-small">+ Adicionar lote</button></div><p class="muted">Os lotes são liberados na ordem abaixo, respeitando datas e estoque.</p><div class="stack" id="lot-list"></div></div><div class="hstack"><button type="button" id="save-draft" class="action action-muted">Salvar como rascunho</button><button type="submit" class="action" id="save-event">${existing?'Salvar alterações':'Salvar evento'}</button><button type="button" id="publish" class="action action-outline">Publicar evento</button></div><p class="error" id="event-error" role="alert"></p></form>`);function drawLots(){let list=$('#lot-list');list.innerHTML=lots.map((l,i)=>`<div class="lot-edit" data-i="${i}"><div class="hstack between"><strong>Lote ${i+1}</strong><div class="hstack"><button type="button" data-move="-1" class="action action-muted is-small" ${i===0?'disabled':''}>↑</button><button type="button" data-move="1" class="action action-muted is-small" ${i===lots.length-1?'disabled':''}>↓</button><button type="button" data-remove class="action action-danger is-small" ${lots.length===1?'disabled':''}>Remover</button></div></div><div class="form-grid">${field('Nome','lotname'+i,l.name,'text','required maxlength="80"')}${field('Preço (R$)','price'+i,(l.price/100).toFixed(2),'number','required min="1" step="0.01" max="100000"')}${field('Quantidade','capacity'+i,l.capacity,'number','required min="1" max="1000000"')}${field('Início das vendas','opens'+i,local(l.opens),'datetime-local')}${field('Fim das vendas','closes'+i,local(l.closes),'datetime-local')}<div class="field"><label for="active${i}">Ativo</label><input id="active${i}" type="checkbox" ${l.active?'checked':''}></div></div></div>`).join('');$$('[data-remove]',list).forEach(b=>b.onclick=()=>{readLots();lots.splice(Number(b.closest('[data-i]').dataset.i),1);drawLots();});$$('[data-move]',list).forEach(b=>b.onclick=()=>{readLots();let i=Number(b.closest('[data-i]').dataset.i),j=i+Number(b.dataset.move);[lots[i],lots[j]]=[lots[j],lots[i]];drawLots();});}function readLots(){lots=lots.map((l,i)=>({...l,name:$('#lotname'+i).value,price:Math.round(Number($('#price'+i).value)*100),capacity:Number($('#capacity'+i).value),opens:utc($('#opens'+i).value),closes:utc($('#closes'+i).value),active:$('#active'+i).checked}));}drawLots();bind('#add-lot','click',()=>{readLots();lots.push({name:`${lots.length+1}º lote`,price:6000,capacity:100,active:1});drawLots();});bind('#flyer','change',async ev=>{let f=ev.currentTarget.files[0];if(!f)return;if(f.size>3e6){toast('Arquivo acima de 3 MB.');ev.currentTarget.value='';return;}let reader=new FileReader();reader.onload=()=>{imageData=reader.result;$('#preview').src=imageData;};reader.readAsDataURL(f);});async function save(setStatus,button){let form=$('#event-form');if(!form.reportValidity())return;if(setStatus)$('#event-status').value=setStatus;await guarded(button,async()=>{readLots();let data=Object.fromEntries(new FormData(form));data.age=Number(data.age);data.starts=utc(data.starts);data.ends=utc(data.ends);data.lots=lots;data.imageData=imageData;if(data.status==='cancelled'&&e.status!=='cancelled'&&!confirm('Cancelar o evento? Esta ação não pode ser revertida.'))return;await api('/admin/events'+(existing?'/'+id:''),existing?'PUT':'POST',data);location.href='/admin/eventos';});}bind('#event-form','submit',ev=>{ev.preventDefault();save(null,$('#save-event'));});bind('#save-draft','click',ev=>save('draft',ev.currentTarget));bind('#publish','click',ev=>save('published',ev.currentTarget));}
async function adminSales(){let orders=await api('/admin/orders'),events=await api('/admin/events');adminShell('Vendas e pedidos',`<div class="surface-panel stack"><div class="form-grid"><div class="field"><label for="filter-event">Evento</label><select id="filter-event"><option value="">Todos os eventos</option>${events.map(e=>`<option value="${esc(e.id)}">${esc(e.title)}</option>`).join('')}</select></div><div class="field"><label for="filter-status">Status</label><select id="filter-status"><option value="">Todos</option>${['paid','pending','expired','review','refunding','refunded','charged_back'].map(s=>`<option value="${s}">${status[s]}</option>`).join('')}</select></div></div><div class="hstack between"><p class="muted" id="sales-total"></p><button id="csv-sales" class="action action-muted is-small">Exportar CSV</button></div><div id="sales-list"></div></div><section class="section compact"><div class="surface-panel stack"><h2>Conciliação de pagamentos</h2><p class="muted">Pagamentos divergentes, duplicados ou aprovados após perda da reserva devem ser revisados com o Mercado Pago. Não considere o pedido aprovado até que o sistema confirme a emissão.</p><div id="payments"></div></div></section>`);function filtered(){return orders.filter(o=>(!$('#filter-event').value||o.event_id===$('#filter-event').value)&&(!$('#filter-status').value||o.status===$('#filter-status').value));}function draw(){let list=filtered();$('#sales-total').textContent=`${list.length} pedido(s) • ${money(list.filter(o=>o.status==='paid').reduce((a,o)=>a+o.total,0))} em vendas aprovadas`;$('#sales-list').innerHTML=table(['Pedido','Evento / lote','Comprador','Quantidade','Total','Status','Pagamento','Ação'],list.map(o=>[`<a href="/pedido/${esc(o.id)}">${esc(o.id.slice(0,8))}</a>`,esc(o.title)+' / '+esc(o.lot),esc(o.name)+'<br><small>'+esc(o.email)+'</small>',o.qty,money(o.total),pill(o.status),esc(o.payment_id||'—'),['paid','review','refunding'].includes(o.status)&&o.payment_id?`<button class="action action-danger is-small" data-refund="${esc(o.id)}">Reembolsar</button>`:'—']));$$('[data-refund]').forEach(b=>b.onclick=()=>{if(confirm('Solicitar reembolso integral? Ingressos serão invalidados.'))guarded(b,async()=>{let r=await api('/admin/orders/'+b.dataset.refund+'/refund','POST');if(!r.ok)toast(r.message||'Reembolso em análise.');orders=await api('/admin/orders');draw();});});}draw();bind('#filter-event','change',draw);bind('#filter-status','change',draw);bind('#csv-sales','click',()=>csv('vendas-long-night.csv',['Pedido','Evento','Comprador','E-mail','Quantidade','Total centavos','Status','Pagamento'],filtered().map(o=>[o.id,o.title,o.name,o.email,o.qty,o.total,o.status,o.payment_id||''])));let payments=await api('/admin/payments');$('#payments').innerHTML=table(['Pagamento','Pedido','Status no provedor','Valor','Atualização'],payments.map(p=>[esc(p.payment_id),`<a href="/pedido/${esc(p.order_id)}">${esc(p.order_id?.slice(0,8))}</a>`,esc(p.status),money(p.amount),esc(dt(p.updated))]));}
function csv(name,head,rows){let q=x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};let blob=new Blob(['\uFEFF'+[head,...rows].map(r=>r.map(q).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function participants(){let p=await api('/admin/participants'),events=await api('/admin/events');adminShell('Participantes',`<div class="surface-panel stack"><div class="field"><label for="part-event">Evento</label><select id="part-event"><option value="">Todos</option>${events.map(e=>`<option value="${esc(e.id)}">${esc(e.title)}</option>`).join('')}</select></div><div class="hstack between"><p id="part-count" class="muted"></p><button class="action action-muted is-small" id="csv-part">Exportar CSV</button></div><div id="part-list"></div></div>`);let f=()=>p.filter(x=>!$('#part-event').value||x.event_id===$('#part-event').value);function draw(){let list=f();$('#part-count').textContent=`${list.length} ingressos · ${list.filter(x=>x.used_at&&!x.void).length} entradas confirmadas`;$('#part-list').innerHTML=table(['Comprador','E-mail','Evento','Lote','Status','Entrada'],list.map(x=>[esc(x.name),esc(x.email),esc(x.title),esc(x.lot),pill(x.void?'cancelled':x.status),x.used_at?esc(dt(x.used_at)):'—']));}draw();bind('#part-event','change',draw);bind('#csv-part','click',()=>csv('participantes-long-night.csv',['Nome','Email','Evento','Lote','Status','Entrada'],f().map(x=>[x.name,x.email,x.title,x.lot,x.void?'cancelled':x.status,x.used_at?dt(x.used_at):''])));}
async function coupons(){let events=await api('/admin/events'),list=await api('/admin/coupons');adminShell('Cupons promocionais',`<div class="split"><div class="surface-panel stack"><h2>Novo cupom</h2><form id="coupon-form" class="stack">${field('Código','code','','text','required maxlength="30" pattern="[A-Za-z0-9_-]+"')}${field('Desconto (%)','percent','10','number','required min="1" max="90"')}<div class="field"><label for="event_id">Evento</label><select name="event_id" id="event_id" required><option value="">Selecione</option>${events.map(e=>`<option value="${esc(e.id)}">${esc(e.title)}</option>`).join('')}</select></div><button class="action" type="submit">Criar cupom</button></form></div><div class="surface-panel stack"><h2>Cupons cadastrados</h2><div id="coupons-list"></div></div></div>`);function draw(){$('#coupons-list').innerHTML=table(['Código','Evento','Desconto','Ação'],list.map(c=>[esc(c.code),esc(c.title),c.percent+'%',`<button class="action action-muted is-small" data-code="${esc(c.code)}" data-active="${c.active}">${c.active?'Desativar':'Ativar'}</button>`]));$$('[data-code]').forEach(b=>b.onclick=()=>guarded(b,async()=>{await api('/admin/coupons/'+b.dataset.code,'PUT',{active:b.dataset.active!=='1'});list=await api('/admin/coupons');draw();}));}draw();bind('#coupon-form','submit',e=>{e.preventDefault();let f=e.currentTarget;guarded($('button[type=submit]',f),async()=>{let b=Object.fromEntries(new FormData(f));b.percent=Number(b.percent);await api('/admin/coupons','POST',b);f.reset();list=await api('/admin/coupons');draw();toast('Cupom criado.');});});}
function settings(){adminShell('Configurações',`<div class="split"><div class="surface-panel stack"><h2>Pagamentos</h2><p>Modo atual: <strong>${config.mode==='demo'?'Demonstração local':'Mercado Pago'}</strong></p><p class="muted">As credenciais financeiras são configuradas no arquivo privado .env do servidor. Nunca são inseridas no navegador ou publicadas no GitHub.</p><p>Notificações por e-mail: ${config.emailEnabled?'configuradas':'não configuradas'}</p><a class="inline-link" href="https://www.mercadopago.com.br/developers/panel" target="_blank" rel="noopener noreferrer">Painel do Mercado Pago ↗</a></div><div class="surface-panel stack"><h2>Alterar senha da equipe</h2><form id="pw-form" class="stack"><div class="field"><label for="role">Conta</label><select name="role" id="role"><option value="admin">Administrador</option><option value="staff">Portaria</option></select></div>${field('Senha atual do administrador','current','','password','required autocomplete="current-password"')}${field('Nova senha','password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<button class="action" type="submit">Atualizar senha</button></form></div></div>`);bind('#pw-form','submit',ev=>{ev.preventDefault();let f=ev.currentTarget;guarded($('button',f),async()=>{let b=Object.fromEntries(new FormData(f));await api('/admin/password','POST',b);if(b.role==='admin'){location.href='/entrar';}else{f.reset();toast('Senha da portaria atualizada.');}});});}
async function admin(){if(!authRequired(['admin']))return;if(route==='/admin')return dashboard();if(route==='/admin/eventos')return adminEvents();if(route.startsWith('/admin/eventos/'))return adminEdit(route.split('/')[3]);if(route==='/admin/vendas')return adminSales();if(route==='/admin/participantes')return participants();if(route==='/admin/cupons')return coupons();if(route==='/admin/configuracoes')return settings();adminShell('Página não encontrada',link('/admin','Voltar ao painel'));}
async function staff(){if(!authRequired(['admin','staff']))return;let events=await api('/staff/events');page(`<div class="scanner stack"><div class="hstack between"><div><div class="eyebrow">Equipe de entrada</div><h1 class="page-title">Validar ingresso</h1></div>${user.role==='admin'?link('/admin','Painel','action-outline is-small'):'<button id="staff-logout" class="action action-muted is-small">Sair</button>'}</div><div class="surface-panel stack"><div class="field"><label for="scan-event">Selecione o evento</label><select id="scan-event"><option value="">Selecione</option>${events.map(e=>`<option value="${esc(e.id)}">${esc(e.title)} — ${esc(day(e.starts))}</option>`).join('')}</select></div><div class="hstack"><button class="action" id="camera">Abrir câmera</button><button class="action action-muted" id="stop-camera" disabled>Parar câmera</button></div><video id="video" playsinline muted hidden></video><p class="muted" id="camera-note">A câmera requer HTTPS ou localhost e navegador com suporte a QR. Caso indisponível, use o código manual.</p><form id="scan-form" class="stack">${field('Código do ingresso','token','','text','required maxlength="100" autocomplete="off" placeholder="LN-..."')}<button class="action" type="submit">Validar ingresso</button></form><div class="result" id="scan-result" role="status" aria-live="polite">Aguardando leitura.</div></div><div class="surface-panel stack"><h2>Buscar participante</h2><form id="staff-search" class="stack"><label for="search-person">Nome, e-mail ou número do pedido</label><input id="search-person" minlength="3" required><button class="action action-outline">Buscar ingresso</button></form><div id="search-results" class="stack"></div></div><div class="surface-panel stack"><div class="hstack between"><h2>Histórico de entradas</h2><button id="history-refresh" class="action action-muted is-small">Atualizar</button></div><div id="scan-history"></div></div></div>`);let busy=false,last='',lastAt=0;async function history(){let h=await api('/staff/history');$('#scan-history').innerHTML=table(['Nome','Evento','Horário'],h.map(x=>[esc(x.name),esc(x.title),esc(dt(x.used_at))]));}async function validate(token){if(busy)return;let eid=$('#scan-event').value;if(!eid){toast('Selecione o evento.');return;}busy=true;try{let r=await api('/staff/checkin','POST',{event:eid,token:token.trim()});let el=$('#scan-result');el.className='result '+r.result;el.innerHTML=`<h2>${esc(r.message)}</h2>${r.name?`<p>${esc(r.name)}</p>`:''}${r.title?`<p>${esc(r.title)} · ${esc(r.lot)}</p>`:''}${r.at?`<small>${esc(dt(r.at))}</small>`:''}`;if(r.result==='valid')await history();}catch(e){err(e);}finally{busy=false;}}function stop(){clearInterval(scanTimer);stream?.getTracks().forEach(t=>t.stop());stream=null;$('#video').hidden=true;$('#camera').disabled=false;$('#stop-camera').disabled=true;}bind('#camera','click',async()=>{if(!$('#scan-event').value){toast('Selecione o evento.');return;}if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){toast('Leitura por câmera indisponível neste navegador. Use o código manual.');return;}try{let detector=new BarcodeDetector({formats:['qr_code']});stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});let video=$('#video');video.srcObject=stream;video.hidden=false;await video.play();$('#camera').disabled=true;$('#stop-camera').disabled=false;scanTimer=setInterval(async()=>{if(busy||video.readyState<2)return;try{let codes=await detector.detect(video);let v=codes[0]?.rawValue;if(v&&(v!==last||Date.now()-lastAt>3500)){last=v;lastAt=Date.now();await validate(v);}}catch{}},350);}catch(e){stop();toast('Não foi possível acessar a câmera: '+e.message);}});bind('#stop-camera','click',stop);bind('#scan-form','submit',e=>{e.preventDefault();let input=$('#token'),v=input.value;input.value='';validate(v);input.focus();});bind('#staff-search','submit',async ev=>{ev.preventDefault();let eid=$('#scan-event').value;if(!eid){toast('Selecione o evento.');return;}try{let result=await api('/staff/search?'+new URLSearchParams({event:eid,q:$('#search-person').value}));$('#search-results').innerHTML=result.map(r=>`<div class="surface-panel stack"><strong>${esc(r.name)}</strong><small>${esc(r.email)} · ${esc(r.lot)}</small><button class="action action-outline" data-confirm="${esc(r.token)}" ${r.used_at||r.void?'disabled':''}>${r.used_at?'Já utilizado':r.void?'Cancelado':'Confirmar entrada'}</button></div>`).join('')||empty('Nenhum ingresso encontrado.');$$('[data-confirm]').forEach(b=>b.onclick=async()=>{if(confirm('Confirma a identidade do participante e autoriza a entrada?')){await validate(b.dataset.confirm);$('#search-results').textContent='Faça uma nova busca para verificar o status.';}});}catch(e){err(e);}});bind('#history-refresh','click',()=>history().catch(err));bind('#staff-logout','click',e=>guarded(e.currentTarget,async()=>{stop();await api('/logout','POST');location.href='/';}));window.addEventListener('pagehide',()=>stream?.getTracks().forEach(t=>t.stop()));await history();}
const photo={hero:'https://images.unsplash.com/photo-1623099405608-83508f309cc2?auto=format&fit=crop&w=2600&q=85',crowd:'https://images.unsplash.com/photo-1768054485661-356cf05ce893?auto=format&fit=crop&w=1800&q=85',dj:'https://images.unsplash.com/photo-1578875388965-064024c15014?auto=format&fit=crop&w=1600&q=85',lights:'https://images.unsplash.com/photo-1759719440818-98681ed4c6b8?auto=format&fit=crop&w=1600&q=85'};
const faq=[['Como compro meu ingresso?','Escolha o evento e o lote, informe seu nome e e-mail e continue para o pagamento. Não é necessário criar conta.'],['Como recebo meu ingresso?','Após a confirmação do pagamento, o ingresso fica disponível pelo link privado. No ambiente real, o link também é enviado por e-mail.'],['O que apresentar na entrada?','Apresente o QR Code do ingresso no celular ou impresso e, se solicitado, um documento de identificação. Cada código permite uma única entrada.'],['Preciso de aplicativo?','Não. Você pode abrir seu ingresso no navegador ou salvar uma cópia em PDF.'],['Preciso de ajuda com uma compra?','Entre em contato com a organização pelo Instagram oficial. Não envie seu QR Code a terceiros.']];
async function homepage(){let events=await api('/events');const next=events.find(e=>Date.parse(e.starts)>Date.now());const cards=events.map((e,i)=>{let l=e.lots.find(l=>l.available&&Date.parse(e.starts)>Date.now());let date=new Date(e.starts);return `<article class="ln-event" id="event-${esc(e.id)}"><div class="ln-flyer"><img src="${esc(e.flyer)}" alt="Flyer de ${esc(e.title)}" loading="lazy"><div class="ln-event-index">${String(i+1).padStart(2,'0')} / AGENDA</div></div><div class="ln-event-body"><div class="ln-date">${esc(day(e.starts))} · ${esc(clock(e.starts))} · ${esc(e.city)}</div><h3>${esc(e.title)}</h3><p>${esc(e.venue)} · ${e.age?e.age+'+':'Classificação livre'}</p><details><summary>Informações do evento</summary><p class="ln-description">${esc(e.description)}</p><p>${esc(e.address)}<br>Início: ${esc(dt(e.starts))}<br>Encerramento: ${esc(dt(e.ends))}</p></details><div class="ln-event-bottom"><div><small>${l?'Ingresso a partir de':'Disponibilidade'}</small><strong>${l?money(l.price):'Indisponível'}</strong>${l?`<small>${esc(l.name)}</small>`:''}</div><button class="action" data-buy="${esc(e.id)}" ${l?'':'disabled'}>${l?'Comprar ingresso →':'Sem vendas'}</button></div></div></article>`;}).join('');shell(`<section id="inicio" class="ln-hero"><img class="ln-hero-photo" src="${photo.hero}" alt="" fetchpriority="high"><div class="ln-hero-scrim"></div><div class="wrap ln-hero-content"><div class="ln-kicker"><span></span> LONG NIGHT / EVENTOS</div><h1>A NOITE<br>É <em>NOSSA.</em></h1><p>Encontre sua próxima experiência. Música, encontros e noites que ficam na memória.</p><a class="action ln-primary" href="/#eventos">Ver próximos eventos <span aria-hidden="true">↘</span></a><span class="ln-hero-note">Ingressos digitais · Compra online · Sem cadastro</span></div>${next?`<div class="ln-next"><span>PRÓXIMA EDIÇÃO</span><strong>${esc(day(next.starts))}</strong><a href="/#event-${esc(next.id)}">${esc(next.title)} →</a></div>`:''}<span class="ln-photo-credit">Fotografia ilustrativa</span></section><section id="eventos" class="ln-section wrap"><div class="ln-section-heading"><div><span class="ln-kicker">01 / AGENDA</span><h2>Próximos eventos<span>.</span></h2></div><p>Escolha sua próxima noite e garanta seu lugar.</p></div><div class="ln-event-grid">${cards||'<div class="surface-panel stack"><h3>Novas datas em breve</h3><p>Acompanhe a Long Night no Instagram para saber das próximas edições.</p><a class="action action-outline" href="https://www.instagram.com/long._night/">Acompanhar no Instagram</a></div>'}</div></section><section class="ln-steps-wrap"><div class="wrap ln-steps"><div><span class="ln-kicker">02 / COMO FUNCIONA</span><h2>Da compra<br>à pista.</h2></div>${[['01','Escolha','Encontre o evento e selecione a quantidade.'],['02','Pague','Finalize no ambiente do Mercado Pago.'],['03','Entre','Mostre o QR Code na portaria.']].map(([n,t,d])=>`<article><span>${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section id="galeria" class="ln-section wrap"><div class="ln-section-heading"><div><span class="ln-kicker">03 / ATMOSFERA</span><h2>Viva a noite<span>.</span></h2></div><a class="ln-text-link" href="https://www.instagram.com/long._night/" target="_blank" rel="noopener noreferrer">Fotos oficiais no Instagram ↗</a></div><div class="ln-gallery">${[[photo.crowd,'Público em um show'],[photo.dj,'DJ se apresentando'],[photo.lights,'Iluminação de pista de dança']].map(([url,alt])=>`<figure><img src="${url}" alt="${alt} — fotografia ilustrativa" loading="lazy"><figcaption>Fotografia de referência</figcaption></figure>`).join('')}</div></section><section id="sobre" class="ln-section wrap"><div class="ln-about"><div><span class="ln-kicker">04 / SOBRE</span><h2>Long Night.<br>Mais que uma noite.</h2></div><div><p>Uma marca dedicada à música, aos encontros e à experiência de viver a noite. Aqui você encontra a agenda, os ingressos e as informações de cada edição em um só lugar.</p><a class="ln-text-link" href="https://www.instagram.com/long._night/" target="_blank" rel="noopener noreferrer">@long._night ↗</a></div></div></section><section id="faq" class="ln-section wrap ln-faq"><div><span class="ln-kicker">05 / INFORMAÇÕES</span><h2>Dúvidas frequentes<span>.</span></h2><p class="muted">Tudo que você precisa saber antes de sair de casa.</p></div><div>${faq.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div></section><dialog id="buy-dialog" aria-labelledby="dialog-title"><div id="buy-content"></div></dialog>`);const dlg=$('#buy-dialog');function openBuy(e){let l=e.lots.find(l=>l.available&&Date.parse(e.starts)>Date.now());if(!l)return;$('#buy-content').innerHTML=`<div class="ln-dialog-top"><div><span class="ln-kicker">GARANTA SEU LUGAR</span><h2 id="dialog-title">Comprar ingresso</h2></div><button id="close-buy" class="action action-muted" aria-label="Fechar compra">×</button></div><div class="ln-dialog-event"><img src="${esc(e.flyer)}" alt=""><div><h3>${esc(e.title)}</h3><small>${esc(dt(e.starts))} · ${esc(e.city)}</small></div></div><form id="buy-form" class="stack">${field('Nome completo','name','','text','required maxlength="100" autocomplete="name"')}${field('E-mail para receber o ingresso','email','','email','required maxlength="160" autocomplete="email"')}<div class="form-grid"><div class="field"><label for="buy-lot">Lote</label><select id="buy-lot" name="lot">${e.lots.filter(x=>x.available).map(x=>`<option value="${esc(x.id)}">${esc(x.name)} — ${money(x.price)}</option>`).join('')}</select></div>${field('Quantidade','qty','1','number',`required min="1" max="${Math.min(l.remaining,10)}"`)}</div><div class="check"><input type="checkbox" id="buy-agree" required><label for="buy-agree">Li os <a href="/termos" target="_blank" rel="noopener noreferrer" class="inline-link">termos</a> e a <a href="/privacidade" target="_blank" rel="noopener noreferrer" class="inline-link">política de privacidade</a>.</label></div><div class="ln-total"><span>Total</span><strong id="buy-total">${money(l.price)}</strong></div><p class="muted">${config.mode==='demo'?'Demonstração: nenhum valor será cobrado.':'Você será redirecionado ao Mercado Pago para pagar via Pix ou cartão.'}</p><p role="alert" class="error" id="buy-error"></p><button type="submit" class="action is-full" id="buy-submit">${config.mode==='demo'?'Criar pedido de teste':'Continuar para pagamento'} →</button></form>`;bind('#close-buy','click',()=>dlg.close());function total(){let lot=e.lots.find(x=>x.id===$('#buy-lot').value);$('#qty').max=Math.min(lot.remaining,10);$('#buy-total').textContent=money(lot.price*Number($('#qty').value||0));}bind('#buy-lot','change',total);bind('#qty','input',total);bind('#buy-form','submit',async ev=>{ev.preventDefault();let btn=$('#buy-submit');btn.disabled=true;$('#buy-error').textContent='';try{let b=Object.fromEntries(new FormData(ev.currentTarget));let o=await api('/guest/orders','POST',{event:e.id,lot:b.lot,qty:Number(b.qty),name:b.name,email:b.email,agree:$('#buy-agree').checked});try{sessionStorage.setItem('ln-order:'+o.id,o.key);}catch{if(config.mode!=='demo'){location.href=o.receipt;return;}}location.href=o.url;}catch(err){$('#buy-error').textContent=err.message;btn.disabled=false;}});if(!dlg.open)dlg.showModal();}$$('[data-buy]').forEach(b=>b.addEventListener('click',()=>openBuy(events.find(e=>e.id===b.dataset.buy))));let id=route.split('/')[2];if(id){let e=events.find(x=>x.id===id);if(e){document.getElementById('event-'+id)?.scrollIntoView();if(route.startsWith('/comprar/'))openBuy(e);}}else if(location.hash){document.getElementById(location.hash.slice(1))?.scrollIntoView();}else if(route!=='/'){document.getElementById(route==='/suporte'?'faq':route.slice(1))?.scrollIntoView();}$$('.ln-gallery img,.ln-hero-photo').forEach(img=>img.addEventListener('error',()=>{img.hidden=true;}));}
function legal(){const privacy=route==='/privacidade';page(`<div class="surface-panel stack"><span class="eyebrow">Informações legais</span><h1 class="page-title">${privacy?'Política de privacidade':'Termos de uso'}</h1><p class="notice">${config.mode==='demo'?'Modelo preliminar: requer revisão e identificação do responsável antes de publicar.':'Consulte a organização para informações de atendimento e exercício de direitos.'}</p>${privacy?'<h2>Dados utilizados</h2><p>Nome, e-mail, pedido e registros de acesso são utilizados para processar a compra, emitir e validar ingressos e prestar atendimento. O pagamento é processado no Mercado Pago. O site não coleta dados do cartão.</p><h2>Contato e direitos</h2><p>Entre em contato com a organização pelo perfil oficial para solicitar informações, correção ou outras medidas aplicáveis aos seus dados.</p>':'<h2>Compra e entrada</h2><p>O ingresso é liberado somente após confirmação do pagamento. Cada código é individual e pode ser validado uma única vez. Consulte os horários, regras e classificação informados no evento.</p><h2>Cancelamento e atendimento</h2><p>Solicitações de cancelamento, reembolso e suporte devem ser encaminhadas à organização, respeitando a legislação aplicável.</p>'}<a class="inline-link" href="https://www.instagram.com/long._night/">Contato oficial da Long Night</a></div>`);}

async function main(){try{config=await api('/config');user=config.user;if(route==='/'||['/eventos','/galeria','/sobre','/suporte','/evento'].includes(route)||route.startsWith('/evento/')||route.startsWith('/comprar/'))await homepage();else if(route==='/termos'||route==='/privacidade')legal();else if(route==='/entrar')authPage();else if(route==='/meus-ingressos')await ordersPage();else if(route.startsWith('/pedido/'))await orderPage(route.split('/')[2]);else if(route.startsWith('/admin'))await admin();else if(route==='/portaria')await staff();else page(`<h1 class="page-title">Página não encontrada</h1>${link('/','Voltar ao início')}`);}catch(e){page(`<h1 class="page-title">Não foi possível abrir esta página</h1><p class="lead">${esc(e.message)}</p>${link('/','Voltar ao início')}`);}}
main();
return () => {clearTimeout(timer);clearInterval(scanTimer);stream?.getTracks().forEach(t=>t.stop());};
}

